"use strict";

// Reads the AIUB student portal math captcha with a small CTC convolutional
// network. The weights come from model.js (generated by training/export.py),
// which defines AIUB_CAPTCHA_MODEL before this file runs.

var AIUBCaptchaSolver = (function () {
  const W = 200;
  const H = 70;
  const VOCAB = "0123456789+-=?";

  function decodeBase64(b64) {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  // Each layer is stored as int8 weights with one float32 scale per output
  // channel, plus a float32 bias per output channel (batch norm folded in)
  // unless the layer has none.
  function loadLayers(model) {
    const bytes = decodeBase64(model.data);
    const layers = {};
    for (const spec of model.layers) {
      const [outC] = spec.shape;
      const count = spec.shape.reduce((a, b) => a * b, 1);
      const q = new Int8Array(bytes.buffer, spec.offset, count);
      const scale = new Float32Array(bytes.slice(spec.scaleOffset, spec.scaleOffset + outC * 4).buffer);
      const bias =
        spec.biasOffset === undefined
          ? null
          : new Float32Array(bytes.slice(spec.biasOffset, spec.biasOffset + outC * 4).buffer);
      const w = new Float32Array(count);
      const per = count / outC;
      for (let o = 0; o < outC; o++) {
        for (let i = 0; i < per; i++) w[o * per + i] = q[o * per + i] * scale[o];
      }
      layers[spec.name] = { shape: spec.shape, w, bias };
    }
    return layers;
  }

  // 3x3 convolution (padding 1), ReLU and ph x pw max-pool in one pass.
  // Input/output are CHW. Output channels are computed four at a time, one
  // row at a time, so each input value read feeds twelve multiply-adds, and
  // each row is pooled as soon as it is done.
  function convReluPool(input, inC, h, w, layer, ph, pw) {
    const outC = layer.shape[0];
    if (outC % 4) throw new Error(`${outC} output channels is not a multiple of 4`);
    const oh = Math.floor(h / ph);
    const ow = Math.floor(w / pw);
    // The input with a border of zeros, so the inner loop needs no bounds checks.
    const rowLen = w + 2;
    const planeLen = (h + 2) * rowLen;
    const padded = new Float32Array(inC * planeLen);
    for (let c = 0; c < inC; c++) {
      for (let y = 0; y < h; y++) {
        padded.set(input.subarray((c * h + y) * w, (c * h + y + 1) * w), c * planeLen + (y + 1) * rowLen + 1);
      }
    }
    // Starting the pool at 0 applies the ReLU.
    const out = new Float32Array(outC * oh * ow);
    const acc = new Float32Array(4 * w);
    const kw = layer.w;
    const kStride = inC * 9;
    for (let o = 0; o < outC; o += 4) {
      // Rows past the last full pooling window are never used.
      for (let y = 0; y < oh * ph; y++) {
        for (let j = 0; j < 4; j++) acc.fill(layer.bias[o + j], j * w, (j + 1) * w);
        for (let c = 0; c < inC; c++) {
          for (let ky = 0; ky < 3; ky++) {
            const k = o * kStride + c * 9 + ky * 3;
            const a0 = kw[k], a1 = kw[k + 1], a2 = kw[k + 2];
            const b0 = kw[k + kStride], b1 = kw[k + kStride + 1], b2 = kw[k + kStride + 2];
            const c0 = kw[k + 2 * kStride], c1 = kw[k + 2 * kStride + 1], c2 = kw[k + 2 * kStride + 2];
            const d0 = kw[k + 3 * kStride], d1 = kw[k + 3 * kStride + 1], d2 = kw[k + 3 * kStride + 2];
            const r = c * planeLen + (y + ky) * rowLen;
            let s0 = padded[r];
            let s1 = padded[r + 1];
            for (let x = 0; x < w; x++) {
              const s2 = padded[r + x + 2];
              acc[x] += a0 * s0 + a1 * s1 + a2 * s2;
              acc[w + x] += b0 * s0 + b1 * s1 + b2 * s2;
              acc[2 * w + x] += c0 * s0 + c1 * s1 + c2 * s2;
              acc[3 * w + x] += d0 * s0 + d1 * s1 + d2 * s2;
              s0 = s1;
              s1 = s2;
            }
          }
        }
        const py = Math.floor(y / ph);
        for (let j = 0; j < 4; j++) {
          const row = acc.subarray(j * w, (j + 1) * w);
          const base = ((o + j) * oh + py) * ow;
          for (let x = 0; x < ow; x++) {
            let m = out[base + x];
            for (let dx = 0; dx < pw; dx++) {
              const v = row[x * pw + dx];
              if (v > m) m = v;
            }
            out[base + x] = m;
          }
        }
      }
    }
    return { data: out, h: oh, w: ow };
  }

  // 3x3 max filter (stride 1) on a single-channel h x w image.
  function dilate3x3(input, h, w) {
    const out = new Float32Array(h * w);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        let m = 0;
        for (let dy = -1; dy <= 1; dy++) {
          const yy = y + dy;
          if (yy < 0 || yy >= h) continue;
          for (let dx = -1; dx <= 1; dx++) {
            const xx = x + dx;
            if (xx < 0 || xx >= w) continue;
            const v = input[yy * w + xx];
            if (v > m) m = v;
          }
        }
        out[y * w + x] = m;
      }
    }
    return out;
  }

  function sigmoid(v) {
    return 1 / (1 + Math.exp(-v));
  }

  // One direction of an LSTM over T steps of `size`-dim features (T x size,
  // row-major). Gates are ordered i, f, g, o as in PyTorch. Returns T x hidden.
  function lstm(feats, t, size, ih, hh, reverse) {
    const hidden = hh.shape[1];
    const out = new Float32Array(t * hidden);
    const h = new Float32Array(hidden);
    const c = new Float32Array(hidden);
    const gates = new Float32Array(4 * hidden);
    for (let k = 0; k < t; k++) {
      const s = reverse ? t - 1 - k : k;
      const xo = s * size;
      for (let g = 0; g < 4 * hidden; g++) {
        let acc = ih.bias[g];
        const wi = g * size;
        for (let j = 0; j < size; j++) acc += ih.w[wi + j] * feats[xo + j];
        const wh = g * hidden;
        for (let j = 0; j < hidden; j++) acc += hh.w[wh + j] * h[j];
        gates[g] = acc;
      }
      for (let j = 0; j < hidden; j++) {
        const i = sigmoid(gates[j]);
        const f = sigmoid(gates[hidden + j]);
        const g = Math.tanh(gates[2 * hidden + j]);
        const o = sigmoid(gates[3 * hidden + j]);
        c[j] = f * c[j] + i * g;
        h[j] = o * Math.tanh(c[j]);
        out[s * hidden + j] = h[j];
      }
    }
    return out;
  }

  let layers = null;

  // Convolution layers in order, with the max-pool size (height, width) after each.
  const CONVS = [
    ["c1", 2, 2],
    ["c2", 2, 2],
    ["c3", 2, 1],
    ["c4", 2, 1],
  ];

  // Mirrors Net.forward in training/train.py. Returns logits laid out (C, T).
  function forward(mask) {
    layers = layers || loadLayers(AIUB_CAPTCHA_MODEL);
    let p = { data: dilate3x3(mask, H, W), h: H, w: W };
    let ch = 1;
    for (const [name, ph, pw] of CONVS) {
      const layer = layers[name];
      p = convReluPool(p.data, ch, p.h, p.w, layer, ph, pw);
      ch = layer.shape[0];
    }
    const x = p.data;
    // One feature vector per column, indexed channel * height + row.
    const t = p.w;
    const size = ch * p.h;
    const feats = new Float32Array(t * size);
    for (let c = 0; c < ch; c++) {
      for (let y = 0; y < p.h; y++) {
        for (let s = 0; s < t; s++) feats[s * size + c * p.h + y] = x[(c * p.h + y) * t + s];
      }
    }
    const fwd = lstm(feats, t, size, layers.fwd_ih, layers.fwd_hh, false);
    const bwd = lstm(feats, t, size, layers.bwd_ih, layers.bwd_hh, true);
    const hidden = layers.fwd_hh.shape[1];
    const out = layers.out;
    const classes = out.shape[0];
    const logits = new Float32Array(classes * t);
    for (let s = 0; s < t; s++) {
      for (let k = 0; k < classes; k++) {
        let acc = out.bias[k];
        const wk = k * 2 * hidden;
        for (let j = 0; j < hidden; j++) {
          acc += out.w[wk + j] * fwd[s * hidden + j];
          acc += out.w[wk + hidden + j] * bwd[s * hidden + j];
        }
        logits[k * t + s] = acc;
      }
    }
    return { logits, classes, t };
  }

  // The decoder considers "a+b=?" and "a-b=?" with operands 1 to 99 and a
  // result that is not negative, which covers every captcha the portal asks.
  const MAX_OPERAND = 99;
  const MAX_ANSWER = 2 * MAX_OPERAND;
  const cls = (ch) => VOCAB.indexOf(ch) + 1;
  const DIGITS = Array.from("0123456789", cls);
  const PLUS = cls("+");
  const MINUS = cls("-");
  const EQUALS = cls("=");
  const QUESTION = cls("?");

  // Probability of each answer 0..MAX_ANSWER: the CTC probability of every
  // expression the portal can ask, summed over the expressions with that
  // answer. Expressions are built one character at a time, and each prefix
  // keeps the CTC forward variables of its last label and the blank after it
  // (index s + 1 is frame s; index 0 is before the first frame), so
  // expressions sharing a prefix share its work.
  function answerProbs({ logits, classes, t }) {
    const y = new Float64Array(classes * t);
    for (let s = 0; s < t; s++) {
      let max = -Infinity;
      for (let k = 0; k < classes; k++) max = Math.max(max, logits[k * t + s]);
      let sum = 0;
      for (let k = 0; k < classes; k++) sum += y[k * t + s] = Math.exp(logits[k * t + s] - max);
      for (let k = 0; k < classes; k++) y[k * t + s] /= sum;
    }
    // One prefix per depth: a, a, op, b, b, =, ? is the longest expression.
    const depth = Array.from({ length: 8 }, () => ({
      last: new Float64Array(t + 1),
      blank: new Float64Array(t + 1),
      ch: -1,
    }));
    const root = depth[0];
    root.blank[0] = 1;
    for (let s = 0; s < t; s++) root.blank[s + 1] = root.blank[s] * y[s];
    function extend(d, ch) {
      const prev = depth[d - 1];
      const cur = depth[d];
      const yc = ch * t;
      cur.ch = ch;
      for (let s = 0; s < t; s++) {
        const from = prev.blank[s] + (ch === prev.ch ? 0 : prev.last[s]);
        cur.last[s + 1] = (cur.last[s] + from) * y[yc + s];
        cur.blank[s + 1] = (cur.blank[s] + cur.last[s]) * y[s];
      }
      return d;
    }
    const probs = new Float64Array(MAX_ANSWER + 1);
    function finish(d, answer) {
      const e = extend(extend(d + 1, EQUALS) + 1, QUESTION);
      probs[answer] += depth[e].last[t] + depth[e].blank[t];
    }
    function operand(d, max, use) {
      for (let first = 1; first <= 9 && first <= max; first++) {
        const d1 = extend(d, DIGITS[first]);
        use(d1, first);
        for (let second = 0; second <= 9 && first * 10 + second <= max; second++) {
          use(extend(d1 + 1, DIGITS[second]), first * 10 + second);
        }
      }
    }
    operand(1, MAX_OPERAND, (da, a) => {
      operand(extend(da + 1, PLUS) + 1, MAX_OPERAND, (db, b) => finish(db, a + b));
      operand(extend(da + 1, MINUS) + 1, a, (db, b) => finish(db, a - b));
    });
    return probs;
  }

  // 1 where the pixel is the captcha's pure text blue (#0000FF).
  function maskFromRGBA(rgba) {
    const mask = new Float32Array(W * H);
    for (let i = 0; i < W * H; i++) {
      const r = rgba[i * 4];
      const g = rgba[i * 4 + 1];
      const b = rgba[i * 4 + 2];
      mask[i] = r < 25 && g < 25 && b > 230 ? 1 : 0;
    }
    return mask;
  }

  // Lowest probability at which an answer is trusted.
  const MIN_CONFIDENCE = 0.97;

  // rgba: Uint8ClampedArray of a 200x70 image. Returns the most probable
  // answer, its probability among all answers the portal can ask for, and
  // whether that probability is at least minConfidence (default
  // MIN_CONFIDENCE).
  function solveRGBA(rgba, minConfidence = MIN_CONFIDENCE) {
    const probs = answerProbs(forward(maskFromRGBA(rgba)));
    let answer = 0;
    let total = 0;
    for (let a = 0; a <= MAX_ANSWER; a++) {
      total += probs[a];
      if (probs[a] > probs[answer]) answer = a;
    }
    if (!(total > 0)) return { answer: null, confidence: 0, confident: false };
    const confidence = probs[answer] / total;
    return { answer, confidence, confident: confidence >= minConfidence };
  }

  return { W, H, MIN_CONFIDENCE, solveRGBA };
})();

if (typeof module !== "undefined") module.exports = AIUBCaptchaSolver;
